---RefreshQuestDetail 刷新关卡详情
---@param questId integer @ 关卡id
---@param currentQuestId integer @ 当前正在挑战的关卡id
---@param hpPercent number @ 血量百分比
function GachaCoinQuestDetailInfo:RefreshQuestDetail(questId, currentQuestId, hpPercent)
    -- 刷新是否正在挑战其他关卡
    self:RefreshQuestHint(questId, currentQuestId)

    -- 刷新关卡信息
    self:RefreshQuestInfo(questId, hpPercent)
end

---RefreshQuestHint 刷新关卡正在挑战的提示
---@param questId integer @ 关卡id
---@param currentQuestId integer @ 当前正在挑战的关卡id
function GachaCoinQuestDetailInfo:RefreshQuestHint(questId, currentQuestId)
    local questType = GCQUtils.GetGachaCoinQuestTypeById(questId)
    local isChallengeQuest = GCQConstants.Defines.QuestType.Challenge == questType
    -- 正在挑战其他关卡的文字
    if not isChallengeQuest and GCQUtils.CheckCurrentQuestId(currentQuestId) and questId ~= currentQuestId then
        KTool.SetActive(self.HintBg, true)
        -- 刷新正在挑战文字
        local currentQuestConfig = GCQUtils.GetGachaCoinQuestConfigById(currentQuestId)
        if not isNull(currentQuestConfig) then
            local hintStr = localize(string.format(
                '%s关卡正在挑战中', currentQuestConfig.name
            ))
            self.HintLabel.text = hintStr
        else
            -- 未找到关卡配置？
            self.HintLabel.text = localize('其他关卡正在挑战中')
        end
    else
        -- 隐藏正在挑战的提示文字
        KTool.SetActive(self.HintBg, false)
    end
end

---RefreshQuestInfo 刷新关卡信息
---@param questId integer @ 关卡id
---@param hpPercent number @ 血量百分比
function GachaCoinQuestDetailInfo:RefreshQuestInfo(questId, hpPercent)
    local questType = GCQUtils.GetGachaCoinQuestTypeById(questId)
    -- 挑战模式 隐藏boss血量信息
    local isChallenge = GCQConstants.Defines.QuestType.Challenge == questType
    --KTool.SetActive(self.BossHpInfo.gameObject, not isChallenge)
    CfUtils.PlayAnimator(self.BossHpInfo, isChallenge and "Go" or "Back")
        local questConfig = GCQUtils.GetGachaCoinQuestConfigById(questId)
        if not isNull(questConfig) then
            local showMonsterId = checkInt(questConfig.monsterShow)
            -- boss名字
            local monsterConfig = GCQUtils.GetMonsterConfig(showMonsterId)
            local name = ''
            if nil ~= monsterConfig then
                name = monsterConfig.name
            end
            self.BossNameLabel.text = name

            -- boss血量文字 两位小数
            local hpPercent_ = Mathf.Floor(hpPercent * 10000) * 0.01
            local hpint = Mathf.Floor(hpPercent_)
            local hpfloat = Mathf.Floor((hpPercent_ - hpint) * 100)

            self.HpLabel.text = string.format(
                    '<size=46>%d</size>.%02d%%', hpint, hpfloat
            )

            -- 血条
            if not isNull(hpPercent) then
                self.HpBar.value = hpPercent
            end
            local rgbStr = questConfig.rgb
            local rgbInfo = parse_strings(rgbStr, ';')
            if not isNull(rgbInfo[1]) then
                self.HpFill.color = XLuaUtils.HexToColor(rgbInfo[1])
            end

            -- 血量奖励文字
            if not isNull(questConfig.perNum) and not isNull(questConfig.perRewardNum) then
                local str = localize(string.format('每造成%d%%可获得%d', checkInt(questConfig.perNum), checkInt(questConfig.perRewardNum)))
                self.HpHintLabel.text = str
            end

            -- 血量奖励道具
            local goodsPath = GoodsConfMgr:GetPhotoPathById(checkInt(questConfig.perReward))
            self.CoinIcon:LoadSprite(goodsPath)

        end
end




return GachaCoinQuestDetailInfo